import {state,esc} from '../../lib/store.js';import {panel,button,empty} from '../pixel/primitives.js';
export function library(ui){let files=state.files.filter(f=>(!ui.fileSearch||[f.name,f.tags].join(' ').toLowerCase().includes(ui.fileSearch.toLowerCase()))&&(!ui.fileCategory||f.category===ui.fileCategory));if(ui.fileSort==='recent')files=[...files].sort((a,b)=>(b.lastOpened||0)-(a.lastOpened||0));return `<div class="notice">LOCAL ONLY / 由你主动选择文件。内容保存在当前浏览器的 IndexedDB，不上传服务器。支持 PDF、DOCX、EPUB、TXT，单文件上限 30 MB；相同文件自动跳过。目录授权仅在本次导入使用。</div><div class="dropzone" id="dropzone"><div class="eyebrow">CONNECT LOCAL LIBRARY</div><p>选择电脑上的文献文件夹，或将文件拖到这里。</p><div class="actions">${button('连接本地文件夹','folder-connect','','primary')}${button('选择文件','file-pick')}<input id="file-picker" type="file" accept=".pdf,.docx,.epub,.txt" multiple hidden></div><p class="micro">不支持文件夹授权时，可使用“选择文件”或拖拽。DOCX / EPUB 提供本地下载打开。</p><p id="import-status" role="status"></p></div><form class="searchbar" data-form="file-search"><input name="q" value="${esc(ui.fileSearch)}" placeholder="搜索文件名或标签" aria-label="搜索资料"><select name="category" aria-label="资料分类"><option value="">全部分类</option>${['论文','课程资料','学习资料','笔记','其他'].map(c=>`<option ${ui.fileCategory===c?'selected':''}>${c}</option>`).join('')}</select><select name="sort" aria-label="排序"><option value="added">导入顺序</option><option value="recent" ${ui.fileSort==='recent'?'selected':''}>最近打开</option></select><button class="button">筛选</button></form>${panel('LOCAL FILES',files.length?`<div class="filelist"><table><thead><tr><th>FILE</th><th>TYPE / SIZE</th><th>CATEGORY</th><th>TAGS</th><th>LAST OPENED</th><th>ACTION</th></tr></thead><tbody>${files.map(f=>`<tr><td>${esc(f.name)}</td><td>${f.type}<br>${(f.size/1024).toFixed(0)} KB</td><td><select data-change="file-category" data-id="${f.id}" aria-label="${esc(f.name)}分类">${['论文','课程资料','学习资料','笔记','其他'].map(c=>`<option ${f.category===c?'selected':''}>${c}</option>`).join('')}</select></td><td><input data-change="file-tags" data-id="${f.id}" value="${esc(f.tags)}" aria-label="${esc(f.name)}标签" placeholder="标签"></td><td>${f.lastOpened?new Date(f.lastOpened).toLocaleDateString('zh-CN'):'尚未打开'}</td><td><div class="actions">${button(f.type==='PDF'||f.type==='TXT'?'打开':'下载打开','file-open',`data-id="${f.id}"`,'small')}${button('关联文献','file-paper',`data-id="${f.id}"`,'small')}${button('移除','file-delete',`data-id="${f.id}"`,'small danger')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('资料库还空着。导入一篇文献，开始建立自己的知识档案。'))}`}
